parameters.text:
=```
Analyze this hotel booking data and provide predictions:

Current Statistics:
- Total Revenue: ${{$json.totalRevenue}}
- Total Guests: {{$json.totalGuests}}
- Total Bookings: {{$json.totalBookings}}
- Average Satisfaction: {{$json.avgSatisfaction}}/5
- Average Nights Stay: {{$json.avgNightsStay}}
- Room Types: {{JSON.stringify($json.roomTypes)}}

Based on this data, provide:
1. Next year, month & 7 days revenue prediction with growth rate
2. Expected number of guests next year, month & 7 days
3. Top 3 actionable insights for improvement
4. Seasonal trends and recommendations

Format response as JSON with keys: nextYearRevenue, nextYearGuests, growthRate, insights, recommendations

parameters.jsCode:
const statisticsItem = $('Calculate Statistics').first().json;
const aiResponse = $input.first().json.output;

// Parse AI response - extract JSON from markdown code blocks if present
let aiPredictions = {};
try {
  // Remove markdown code blocks (```json and ```)
  let cleanedResponse = aiResponse.trim();

  // Check if response contains markdown code blocks
  const jsonMatch = cleanedResponse.match(/```(?:json)?\s*\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    // Extract JSON from code block
    cleanedResponse = jsonMatch[1].trim();
  }

  // Parse the cleaned JSON
  aiPredictions = JSON.parse(cleanedResponse);

} catch (e) {
  console.error('Failed to parse AI response:', e);
  console.error('Raw AI response:', aiResponse);
  // Fallback if AI doesn't return valid JSON
  aiPredictions = {
    nextYearRevenue: statisticsItem.totalRevenue * 1.15,
    nextMonthRevenue: Math.round((statisticsItem.totalRevenue / 12) * 1.15),
    next7DaysRevenue: Math.round((statisticsItem.totalRevenue / 52) * 1.15),
    nextYearGuests: Math.round(statisticsItem.totalGuests * 1.15),
    nextMonthGuests: Math.round((statisticsItem.totalGuests / 12) * 1.15),
    next7DaysGuests: Math.round((statisticsItem.totalGuests / 52) * 1.15),
    growthRate: {
      yearly: 0.15,
      monthly: 0.15,
      weekly: 0.15
    },
    insights: [
      "Maintain service quality", 
      "Focus on high-satisfaction room types", 
      "Optimize pricing strategy"
    ],
    recommendations: [
      "Implement loyalty program", 
      "Expand marketing efforts", 
      "Improve operational efficiency"
    ],
    seasonalTrends: {
      trends: "Insufficient data to determine seasonal trends",
      recommendations: "Collect historical data to identify patterns"
    }
  };
}

// Combine statistics with AI predictions
const dashboardData = {
  ...statisticsItem,
  predictions: aiPredictions,
  lastUpdated: new Date().toISOString()
};

return [{ json: dashboardData }];

// Transform Firebase data into usable format
const items = $input.all();
const rawData = items[0].json;

// Get webhook data as fallback
const webhookData = $('Receive Chat Message').first().json.body;

// Convert Firebase object to array
const bookingsArray = Object.entries(rawData).map(([key, booking]) => ({
  id: key,
  customer_name: booking["Full Name"] || booking.customer_name || webhookData.customerName || "",
  customer_email: booking["Email Address"] || booking.customer_email || webhookData.customerEmail || "",
  nationality: booking["Nationality"] || booking.nationality || "",
  phone_number: booking["Phone Number"] || booking.phone_number || "",
  check_out_date: booking["Check-out Date"] || booking.check_out_date || "",
  guest_number: parseInt(booking["Number of Guests"] || booking.guest_number) || 0,
  room_type: booking["Room Type"] || booking.room_type || "",
  special_requests: booking["Special Requests"] || booking.special_requests || ""
}));

// Return each booking as separate item for processing
return bookingsArray.map(booking => ({ json: booking }));

// Get all input items (for runOnceForAllItems mode)
const input = $input.first();
const firebaseData = input.json;
const items = [];

for (const uniqueId in firebaseData) {
  const booking = firebaseData[uniqueId];
  items.push({
    json: {
      unique_id: input.json.id,
      booking_timestamp: booking.booking_timestamp || input.json.data?.booking_timestamp,
      check_in_date: booking.check_in_date || $input.first().json.body.checkin,
      check_out_date: booking.check_out_date || $input.first().json.body.checkout,
      customer_email: booking.customer_email || $input.first().json.body.customerEmail,
      customer_name: booking.customer_name || $input.first().json.body.customerName,
      guest_number: booking.guest_number || $input.first().json.body.guests,
      guest_satisfaction: booking.guest_satisfaction || input.json.data?.guest_satisfaction,
      room_per_night: booking.room_per_night || input.json.data?.room_per_night,
      room_type: booking.room_type || input.json.data?.room_type,
      spend_nights: booking.spend_nights || ($input.first().json.body.checkout - $input.first().json.body.checkin),
      total_price: booking.total_price || $input.first().json.body.totalPrice,
      hotelname: booking.hotelname || $input.first().json.body.hotelName,
      adminemail: booking.adminemail || $input.first().json.body.adminEmail
    }
  });
}

return items;

// Get the latest booking based on booking_timestamp
const latestBooking = items.reduce((latest, current) => {
  const latestTimestamp = new Date(latest.json.booking_timestamp).getTime();
  const currentTimestamp = new Date(current.json.booking_timestamp).getTime();

  return currentTimestamp > latestTimestamp ? current : latest;
}, items[0]);

// Convert to column-wise format
const columnWiseData = {
  adminemail: latestBooking.json.adminemail,
  booking_timestamp: latestBooking.json.booking_timestamp,
  check_in_date: latestBooking.json.check_in_date,
  check_out_date: latestBooking.json.check_out_date,
  customer_email: latestBooking.json.customer_email,
  customer_name: latestBooking.json.customer_name,
  guest_number: latestBooking.json.guest_number,
  guest_satisfaction: latestBooking.json.guest_satisfaction,
  room_per_night: latestBooking.json.room_per_night,
  room_type: latestBooking.json.room_type,
  spend_nights: latestBooking.json.spend_nights,
  total_price: latestBooking.json.total_price,
  hotelname: latestBooking.json.hotelname
};

return [{ json: columnWiseData }];

